"""Explain the proposed platform and surface the existing JSON demonstration."""
import json
from html import escape
from build import ROOT, head, t, a, footer
from proforma import data


def technical_page():
    project = data()['projects'][0]
    sample = {'nombre': project['name'], 'dominio': project['domain'], 'sector': project['sector'], 'estado': project['status'], 'avance_obra': project['progress'], 'fecha_estimada_entrega': project['delivery'], 'comercializable': True, 'precio_m2_usd': project['m2_price']}
    steps = [
        ('01', 'Gestor central', 'Central manager', 'Comercial y Legal mantienen los proyectos, precios, disponibilidad y fechas en un solo lugar.', 'Sales and Legal maintain projects, prices, availability and dates in one place.'),
        ('02', 'Publicación y feed JSON', 'Publishing and JSON feed', 'La información aprobada alimenta el sitio de marca y los sitios de tus proyectos. El feed comparte los mismos datos con otros sistemas.', 'Approved information feeds the brand website and your project websites. The feed shares the same data with other systems.'),
        ('03', 'CRM y WhatsApp', 'CRM and WhatsApp', 'Las integraciones se definen según tus herramientas. La demo simula un asistente que responde con los datos del proyecto.', 'Integrations are defined around your tools. The demo simulates an assistant answering with project data.'),
    ]
    flow = ''.join(f'<li><span class="overline">{n}</span>{t(es,en,"h2")}{t(copy,copyen,"p")}</li>' for n,es,en,copy,copyen in steps)
    out = head('technical') + f'''<main id="main" class="proposal-main technical-main">
<section class="technical-intro"><span class="overline">{t('CÓMO FUNCIONA','HOW IT WORKS')}</span>{t('Un dato.<br>Toda la red conectada.','One update.<br>A connected network.','h1')}<p>{t('La base técnica es común a los tres niveles. Cambia la forma de explorar los proyectos; la información se gestiona desde el mismo lugar.','All three tiers share the same technical foundation. The way visitors explore projects changes; information is managed in the same place.')}</p><nav class="technical-index" aria-label="Contenido / Contents">{a('El recorrido del dato','The data flow','#flujo')}{a('API / JSON','API / JSON','#api-json')}{a('Exploración 2D y 3D','2D and 3D exploration','#exploracion')}</nav></section>
<section id="flujo" class="technical-section"><ol class="technical-flow">{flow}</ol><p class="technical-note">{t('Arquitectura propuesta. Esta presentación usa datos de ejemplo y simula la gestión y las integraciones.','Proposed architecture. This presentation uses sample data and simulates management and integrations.')}</p>{a('Probar el gestor central','Try the central manager','/demo/#demo-basico','text-link')}</section>
<section id="api-json" class="technical-section technical-api"><div><span class="overline">API / JSON</span>{t('Los mismos datos,<br>también para otros sistemas.','The same data,<br>ready for other systems.','h2')}<p>{t('JSON es un formato de texto que permite compartir información estructurada. El feed propuesto /proyectos.json reúne los datos de los proyectos para que otros servicios puedan leerlos.','JSON is a text format for sharing structured information. The proposed /proyectos.json feed brings project data together so other services can read it.')}</p><p>{t('En cualquiera de los tres niveles, cambia el estado o el avance de obra: el panel JSON se actualiza junto con la tarjeta del sitio y las respuestas simuladas de WhatsApp.','In any of the three tiers, change the status or construction progress: the JSON panel updates alongside the website card and simulated WhatsApp replies.')}</p><div class="technical-actions">{a('Probar el JSON en vivo','Try the live JSON demo','/demo/#api-json','button')}{a('Abrir datos de ejemplo (.json)','Open sample data (.json)','/demo/proyectos-demo.json','text-link')}</div><p class="technical-note">{t('El ejemplo muestra algunos campos del feed. El archivo descargable contiene los datos de la demo; no es una API de producción.','The example shows selected feed fields. The linked file contains the demo dataset; it is not a production API.')}</p></div><figure class="technical-code"><figcaption>{t('EJEMPLO DE FEED · DATOS ILUSTRATIVOS','SAMPLE FEED · ILLUSTRATIVE DATA')}</figcaption><pre tabindex="0" aria-label="JSON"><code>{escape(json.dumps(sample,ensure_ascii=False,indent=2))}</code></pre></figure></section>
<section id="exploracion" class="technical-section"><div class="proposal-section-title">{t('De los datos a la experiencia.','From data to experience.','h2')}<p>{t('Medio añade selección de edificio, piso y departamento en 2D. Alto incorpora la maqueta 3D y visitas virtuales. Ambas experiencias se apoyan en la misma información de unidades.','Mid adds 2D building, floor and apartment selection. High adds the 3D model and virtual visits. Both experiences use the same apartment information.')}</p></div><div class="technical-actions">{a('Ver selección 2D','See 2D selection','/demo/#demo-medio','text-link')}{a('Ver experiencia 3D','See the 3D experience','/demo/?demo=3d#demo-3d','text-link')}</div></section>
<section class="proposal-next"><div>{t('Publicar, conectar y mantener.','Publish, connect and maintain.','h2')}<p>{t('Elegimos las funciones y conexiones que necesita tu proyecto. El primer paso es revisar tus activos, inventario y proceso comercial.','We select the features and connections your project needs. The first step is to review your assets, inventory and sales process.')}</p></div><div>{a('Definir un piloto','Define a pilot','/contacto/','button')}</div></section></main>''' + footer(True) + '</body></html>'
    (ROOT/'como-funciona').mkdir(exist_ok=True)
    (ROOT/'como-funciona/index.html').write_text(out)
